<?php get_header(); ?><main id="main-content" class="site-main container section-space"><?php if ( have_posts() ) : ?><header class="page-header"><p class="eyebrow"><?php esc_html_e( 'Latest', 'meridian-news' ); ?></p><h1><?php bloginfo( 'name' ); ?></h1></header><div class="card-grid"><?php while ( have_posts() ) : the_post(); get_template_part( 'template-parts/content', 'card' ); endwhile; ?></div><?php meridian_news_pagination(); else : ?><section class="empty-state"><h1><?php esc_html_e( 'Nothing published yet', 'meridian-news' ); ?></h1><p><?php esc_html_e( 'Please check back soon for new stories.', 'meridian-news' ); ?></p></section><?php endif; ?></main><?php get_footer(); ?>
